#!/bin/bash
# Uninstall script for LÖVE
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling LÖVE..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping LÖVE if running..."
pkill -f "LÖVE" 2>/dev/null || true

# Remove /Applications/love.app
echo "Removing /Applications/love.app..."
if [ -d "/Applications/love.app" ]; then
    rm -rf "/Applications/love.app" 2>/dev/null || true
elif [ -f "/Applications/love.app" ]; then
    rm -f "/Applications/love.app" 2>/dev/null || true
fi

# Remove binary /Applications/LÖVE.app/love.app/Contents/MacOS/love
echo "Removing binary /Applications/LÖVE.app/love.app/Contents/MacOS/love..."
if [ -f "/Applications/LÖVE.app/love.app/Contents/MacOS/love" ]; then
    rm -f "/Applications/LÖVE.app/love.app/Contents/MacOS/love" 2>/dev/null || true
fi

# Remove $HOME/Library/Saved Application State/org.love2d.love.savedState
echo "Removing $HOME/Library/Saved Application State/org.love2d.love.savedState..."
if [ -d "$HOME/Library/Saved Application State/org.love2d.love.savedState" ]; then
    rm -rf "$HOME/Library/Saved Application State/org.love2d.love.savedState" 2>/dev/null || true
elif [ -f "$HOME/Library/Saved Application State/org.love2d.love.savedState" ]; then
    rm -f "$HOME/Library/Saved Application State/org.love2d.love.savedState" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
